svg.script:
(() => {
  'use strict';
  const svg = document.currentScript?.ownerSVGElement || document.documentElement;
  const find = id => svg.querySelector('#' + id);
  const win = svg.ownerDocument.defaultView;
  if (!win || !win.requestAnimationFrame) return;

  const channel = Object.freeze({
    breath:0, sway:1, ax:2, ay:3, bx:4, by:5, earL:6, earR:7, lockL:8,
    lockR:9, rearL:10, rearR:11, bangM:12, shoulder:13, elbow:14, wrist:15,
    cuff:16, sleeve:17, lid:19, depthX:20, depthY:21,
    earLTip:22, earRTip:23, lockLTip:24, lockRTip:25, rearLTip:26,
    rearRTip:27, bangL:28, bangR:29, bangLTip:30, bangMTip:31, bangRTip:32,
    rearLCos:33,rearLSin:34,rearLTipCos:35,rearLTipSin:36,
    rearRCos:37,rearRSin:38,rearRTipCos:39,rearRTipSin:40,torsoRoll:41,torsoRise:42,
    earLDragCos:43,earLDragSin:44,earLDragX:45,earLDragY:46,
    earRDragCos:47,earRDragSin:48,earRDragX:49,earRDragY:50
  });
  const pose = new Float64Array(1+Math.max(...Object.values(channel)));
  const rad = Math.PI/180;
  const clip = (v,lo,hi) => Math.max(lo,Math.min(hi,v));
  const smooth = (a,b,v) => {const t=clip((v-a)/(b-a),0,1);return t*t*(3-2*t);};
  const mound = (x,y,cx,cy,rx,ry) => Math.exp(-(((x-cx)/rx)**2+((y-cy)/ry)**2));
  const pivotX=1002, pivotY=564;
  // Rest coordinates describe the sewn root, middle hinge and free end.
  // The two angular responses blend into the original Béziers along their rest length.
  const strands = {
    earL:  [[862,86],[716,297],[529,506],channel.earL,channel.earLTip],
    earR:  [[1098,73],[1274,274],[1452,521],channel.earR,channel.earRTip],
    lockL: [[865,210],[860,571],[752,892],channel.lockL,channel.lockLTip],
    lockR: [[1117,233],[1173,446],[1122,652],channel.lockR,channel.lockRTip],
    rearL: [[783,567],[567,781],[420,1001],channel.rearL,channel.rearLTip],
    rearR: [[1196,549],[1348,767],[1490,1001],channel.rearR,channel.rearRTip],
    bangL: [[948,177],[939,304],[984,392],channel.bangL,channel.bangLTip],
    bangM: [[987,190],[997,286],[1016,362],channel.bangM,channel.bangMTip],
    bangR: [[1042,204],[1073,260],[1119,336],channel.bangR,channel.bangRTip]
  };
  function makeEar(side,channels) {
    const [root,,tip]=strands[side],dx=tip[0]-root[0],dy=tip[1]-root[1];
    const length=Math.hypot(dx,dy);
    return {side,root,length,nx:dx/length,ny:dy/length,channels,
      angle:oscillator(1.55,.45),slide:oscillator(1.74,.50)};
  }
  const ears={
    earL:makeEar('earL',[channel.earLDragCos,channel.earLDragSin,channel.earLDragX,channel.earLDragY]),
    earR:makeEar('earR',[channel.earRDragCos,channel.earRDragSin,channel.earRDragX,channel.earRDragY])
  };
  let earGrip=null;
  const earDistance=(ear,x,y)=>(x-ear.root[0])*ear.nx+(y-ear.root[1])*ear.ny;
  const earWeight=(ear,distance)=>smooth(.24,.76,distance/ear.length);
  const headDepth={face:122,hood:86,earL:86,earR:86,lockL:119,lockR:119,
                   bangL:126,bangM:125,bangR:124,fringeBase:125,rearL:44,rearR:44,neck:91};
  const rearChannels={
    rearL:[channel.rearLCos,channel.rearLSin,channel.rearLTipCos,channel.rearLTipSin],
    rearR:[channel.rearRCos,channel.rearRSin,channel.rearRTipCos,channel.rearRTipSin]
  };
  function projectRearBends() {
    for(const name of ['rearL','rearR']){
      const [, , ,upper,lower]=strands[name],[c,s,ct,st]=rearChannels[name];
      const a=pose[upper]*rad,b=pose[lower]*rad;
      pose[c]=Math.cos(a)-1;pose[s]=Math.sin(a);
      pose[ct]=Math.cos(a+b)-Math.cos(a);pose[st]=Math.sin(a+b)-Math.sin(a);
    }
  }
  function bind(x,y,rig) {
    if(rig==='neckL'){
      // Weld the shaded edge to the moving cheek lock, fading inward to the neck.
      const edge=868.7+.55*clip(y-532.1,0,69);
      const hairWeight=1-smooth(edge+14,edge+76,x);
      if(hairWeight===1)return bind(x,y,'lockL');
      if(hairWeight===0)return bind(x,y,'neck');
      const weights=new Map();
      for(const [surface,strength] of [['lockL',hairWeight],['neck',1-hairWeight]]){
        const p=bind(x,y,surface);
        p.k.forEach((key,i)=>{
          const v=weights.get(key)||[0,0];
          v[0]+=p.a[i]*strength;v[1]+=p.b[i]*strength;weights.set(key,v);
        });
      }
      const coeff=[...weights.values()];
      return {x,y,k:[...weights.keys()],a:coeff.map(v=>v[0]),b:coeff.map(v=>v[1])};
    }
    const cx=new Float64Array(pose.length),cy=new Float64Array(pose.length);
    const add=(i,a,b)=>{cx[i]+=a;cy[i]+=b;};
    const turn=(i,ox,oy,w)=>add(i,-(y-oy)*rad*w,(x-ox)*rad*w);
    add(channel.breath,.30,-3.15);
    add(channel.sway,1.65,0);
    const rear=rearChannels[rig];
    if(Object.hasOwn(headDepth,rig)) {
      let w=1;
      if(rig==='neck')w=.86*(1-smooth(505,608,y));
      if(rear)w=.85;
      const anchor=rear?strands[rig][0]:[x,y];
      add(channel.ax,w*(anchor[0]-pivotX),0); add(channel.ay,w*(anchor[1]-pivotY),0);
      add(channel.bx,0,w*(anchor[0]-pivotX)); add(channel.by,0,w*(anchor[1]-pivotY));
      add(channel.depthX,w*headDepth[rig],0);add(channel.depthY,0,w*headDepth[rig]);
    }
    const strand=strands[rig];
    if(rear){
      // The tips are a single rigid part of each curl, also beyond the artboard.
      const [root,hinge]=strand,[c,s,ct,st]=rear;
      const u=smooth(root[1]+5,hinge[1],y), v=smooth(hinge[1]+4,888,y);
      const x0=x-root[0],y0=y-root[1],x1=x-hinge[0],y1=y-hinge[1];
      add(c,u*x0,u*y0);add(s,-u*y0,u*x0);
      add(ct,v*x1,v*y1);add(st,-v*y1,v*x1);
    }else if(strand) {
      const [root,hinge,tip,upper,lower]=strand;
      const along=(p,q)=>{
        const a=q[0]-p[0],b=q[1]-p[1];
        return ((x-p[0])*a+(y-p[1])*b)/(a*a+b*b);
      };
      let u=smooth(.14,1.01,along(root,hinge));
      let v=smooth(.01,.97,along(hinge,tip));
      // The sides of the fringe join above the eye line, just below the hood.
      if(rig==='bangL'||rig==='bangM')u*=smooth(257,329,y);
      if(rig==='bangR')u*=smooth(207,264,y);
      turn(upper,root[0],root[1],u);
      turn(lower,hinge[0],hinge[1],v);
      const ear=ears[rig];
      if(ear){
        // The sewn base stays on the hood. The whole free tip and its stud turn together.
        const w=earWeight(ear,earDistance(ear,x,y)),rx=x-root[0],ry=y-root[1];
        const [cos,sin,shiftX,shiftY]=ear.channels;
        add(cos,w*rx,w*ry);add(sin,-w*ry,w*rx);
        add(shiftX,w,0);add(shiftY,0,w);
      }
    }
    if(rig==='arm') {
      turn(channel.shoulder,801,659,1-smooth(609,821,x));
      turn(channel.elbow,496,563,1-smooth(434,618,x));
      turn(channel.wrist,261,456,1-smooth(216,346,x));
      const cloth=mound(x,y,682,667,62,119)+.48*mound(x,y,263,473,46,71);
      add(channel.cuff,cloth,-.28*cloth);
    }
    if(rig==='coat') {
      const lower=smooth(1100,1229,x)*smooth(677,944,y);
      turn(channel.sleeve,1171,674,lower);
    }
    const edge=rig==='coat'?1-smooth(949,1024,y):1;
    const k=[],a=[],b=[];
    for(let i=0;i<pose.length;i++){
      if(Math.abs(cx[i])+Math.abs(cy[i])<.00001)continue;
      k.push(i);a.push(cx[i]);b.push(cy[i]*edge);
    }
    return {x,y,k,a,b};
  }

  // One orthographic projection of the head. Both eyes, the jaw, nose, mouth
  // and the face backing share the same affine transform and camera depth.
  function projectHead(yaw,pitch,roll) {
    const sy=Math.sin(yaw),cy=Math.cos(yaw),sp=Math.sin(pitch),cp=Math.cos(pitch);
    const sr=Math.sin(roll),cr=Math.cos(roll);
    pose[channel.ax]=cr*cy+sr*sp*sy-1;
    pose[channel.ay]=-sr*cp;
    pose[channel.bx]=sr*cy-cr*sp*sy;
    pose[channel.by]=cr*cp-1;
    pose[channel.depthX]=cr*sy-sr*sp*cy;
    pose[channel.depthY]=sr*sy+cr*sp*cy;
  }
  function headMatrix(z,dx,dy) {
    const ax=pose[channel.ax],ay=pose[channel.ay],bx=pose[channel.bx],by=pose[channel.by];
    const tx=dx+z*pose[channel.depthX]-ax*pivotX-ay*pivotY;
    const ty=dy+z*pose[channel.depthY]-bx*pivotX-by*pivotY;
    return 'matrix('+[1+ax,bx,ay,1+by,tx,ty].map(v=>+v.toFixed(6)).join(' ')+')';
  }
  const faceSolids=['face','brows','lid-folds','face-shadow-receiver','right-human-ear','eye-left','eye-right'].map(find);
  const collarSolids=['collar-stand','coat-lapel','lapel-shade','zipper-assembly'].map(find);
  const hoodSolids=[find('hood-clasp'),find('hood-opening-edge')];
  const bodyRoot=find('character'),[hipX,hipY]=bodyRoot.getAttribute('data-pivot').split(' ').map(Number);
  const tab=find('zipper-pull'), [pinX,pinY]=tab.getAttribute('data-hinge').split(' ').map(Number);
  const pull={angle:0,speed:0,grip:null,target:0,bias:0};
  function paintSolids() {
    bodyRoot.setAttribute('transform','translate(0 '+pose[channel.torsoRise].toFixed(5)+') rotate('+pose[channel.torsoRoll].toFixed(5)+' '+hipX+' '+hipY+')');
    const dx=.30*pose[channel.breath]+1.65*pose[channel.sway],dy=-3.15*pose[channel.breath];
    const torso='translate('+dx.toFixed(5)+' '+dy.toFixed(5)+')';
    for(const el of collarSolids)el.setAttribute('transform',torso);
    tab.setAttribute('transform','rotate('+(pull.angle/rad).toFixed(5)+' '+pinX+' '+pinY+')');
    const face=headMatrix(headDepth.face,dx,dy);
    for(const el of faceSolids)el.setAttribute('transform',face);
    const hood=headMatrix(headDepth.hood,dx,dy);
    for(const el of hoodSolids)el.setAttribute('transform',hood);
  }

  const pairCache=new Map(), points=[], fields=[];
  const token=/[MLCZ]|[-+]?(?:\d*\.\d+|\d+\.?\d*)(?:[eE][-+]?\d+)?/g;
  svg.querySelectorAll('[data-rig] path').forEach(el=>{
    const cuts=(el.getAttribute('data-bind')||'').match(/\d+:\w+/g)||[];
    const ranges=cuts.map(cut=>cut.split(':'));
    let rig=el.closest('[data-rig]').getAttribute('data-rig'),point=0,range=0;
    const v=el.getAttribute('d').match(token);
    const pieces=[];
    for(let i=0;i<v.length;) {
      const t=v[i++];
      if(t==='M'||t==='L'||t==='C'||t==='Z') { pieces.push(t);continue; }
      if(range<ranges.length && point===Number(ranges[range][0]))rig=ranges[range++][1];
      point++;
      const y=v[i++],key=rig+'|'+t+'|'+y;
      let index=pairCache.get(key);
      if(index===undefined) { index=points.length;pairCache.set(key,index);points.push(bind(+t,+y,rig)); }
      pieces.push(index);
    }
    fields.push({el,pieces});
  });
  pairCache.clear();
  const pairs=new Array(points.length);
  function paintSkin() {
    projectRearBends();
    for(let i=0;i<points.length;i++) {
      const p=points[i];let x=p.x,y=p.y;
      for(let j=0;j<p.k.length;j++) {
        const v=pose[p.k[j]]; x+=p.a[j]*v;y+=p.b[j]*v;
      }
      pairs[i]=' '+(Math.round(x*20)/20)+','+(Math.round(y*20)/20);
    }
    for(const f of fields) {
      let d='';
      for(const v of f.pieces) d+=typeof v==='number'?pairs[v]:v;
      f.el.setAttribute('d',d);
    }
    paintSolids();
  }

  const number=/[-+]?(?:\d*\.\d+|\d+\.?\d*)(?:[eE][-+]?\d+)?/g;
  function lidMorph(el) {
    const original=el.getAttribute('d'), target=el.getAttribute('data-closed');
    const sep=original.split(number), a=original.match(number).map(Number), b=target.match(number).map(Number);
    let prev=-1;
    return value=>{
      if(Math.abs(prev-value)<.0001) return;
      prev=value;
      if(value===0||value===1) { el.setAttribute('d',value===0?original:target);return; }
      let d=sep[0];
      for(let i=0;i<a.length;i++)d+=(Math.round((a[i]+(b[i]-a[i])*value)*100)/100)+sep[i+1];
      el.setAttribute('d',d);
    };
  }
  function makeEye(side) {
    const node=find('eye-'+side);
    const iris=find('eye-'+side+'-iris'), inside=find('eye-'+side+'-contents');
    const morphs=[find('eye-'+side+'-aperture'),find('eye-'+side+'-crease'),...node.querySelectorAll('[data-closed]')].map(lidMorph);
    return (blink,gx,gy)=>{
      iris.setAttribute('transform','translate('+(gx*(side==='left'?3.8:4.5)).toFixed(2)+' '+(gy*2.65).toFixed(2)+')');
      for(const fn of morphs)fn(blink);
      inside.setAttribute('visibility',blink>.995?'hidden':'visible');
    };
  }
  const eyes=[makeEye('left'),makeEye('right')];
  const normalEyes=[find('eye-left-normal'),find('eye-right-normal'),find('lid-folds')];
  const squeezedEyes=[find('eye-left-squeeze'),find('eye-right-squeeze')];
  function squeezeEyes(held) {
    for(const el of normalEyes)el.setAttribute('display',held?'none':'inline');
    for(const el of squeezedEyes)el.setAttribute('display',held?'inline':'none');
    svg.setAttribute('data-ear-held',held?'yes':'no');
  }

  // Substepped damped oscillators. Loose parts react to acceleration and continue after the pointer stops.
  function oscillator(hz,zeta) { return {x:0,v:0,w:2*Math.PI*hz,z:zeta}; }
  function advance(s,goal,dt,w=s.w,z=s.z) {
    s.v+=((goal-s.x)*w*w-2*z*w*s.v)*dt;
    s.x+=s.v*dt;
    return s.x;
  }
  const headX=oscillator(1.28,.92),headY=oscillator(1.39,.94);
  const torsoRoll=oscillator(.81,.88),torsoRise=oscillator(.88,.94);
  const irisX=oscillator(3.15,.93),irisY=oscillator(3.05,.92),roll=oscillator(1.18,.86);
  const arm=oscillator(1.02,.78),elbow=oscillator(1.23,.71),wrist=oscillator(1.58,.54);
  const cuff=oscillator(1.71,.46),sleeve=oscillator(1.15,.68);
  function swingPull(dt,baseAcceleration,shoulderAcceleration,sleeveAcceleration,inclination=0) {
    // Damped pendulum about the slider pin. Garment acceleration supplies a small torque.
    // The sleeve and the raised arm lie on opposite sides of the slider.
    const garment=clip(baseAcceleration/83+.25*shoulderAcceleration-.36*sleeveAcceleration,-6,6);
    const torque=pull.grip===null
      ? garment-44*Math.sin(pull.angle+inclination)-2.5*pull.speed
      : 290*(pull.target-pull.angle)-24*pull.speed;
    pull.speed=clip(pull.speed+torque*dt,-4.8,4.8);
    pull.angle+=pull.speed*dt;
    const limit=.84;
    if(Math.abs(pull.angle)>limit){
      pull.angle=Math.sign(pull.angle)*limit;pull.speed*=-.15;
    }
  }
  function chain(name,rootFrequency,tipFrequency,damping,wind,impulse,nod,period,phase) {
    return {joint:strands[name],root:oscillator(rootFrequency,damping),
      tip:oscillator(tipFrequency,damping*.94),wind,impulse,nod,period,phase};
  }
  const chains=[
    chain('earL',1.38,1.10,.55,.88,1.13,-.50,1.12,.1),
    chain('earR',1.22,1.00,.54,.96,1.20,.47,1.04,1.10),
    chain('lockL',1.31,1.02,.56,1.04,1.14,-.25,1.17,-.35),
    chain('lockR',1.57,1.20,.58,1.48,1.49,.27,1.31,.50),
    chain('rearL',.97,.79,.59,1.65,1.46,-.50,.94,-.85),
    chain('rearR',1.03,.87,.54,1.70,1.52,.51,1.04,1.16),
    chain('bangL',1.83,1.42,.59,1.95,2.20,-.37,1.49,-.48),
    chain('bangM',2.16,1.60,.61,1.73,2.01,.28,1.67,.65),
    chain('bangR',1.72,1.33,.57,2.18,2.31,.42,1.42,1.21)
  ];
  let targetX=0,targetY=0, touch=null, gravityX=0,gravityY=0;
  const cursor=svg.createSVGPoint();
  function pointInArt(e){
    if(e.isPrimary===false)return null;
    const m=svg.getScreenCTM();if(!m)return null;
    cursor.x=e.clientX;cursor.y=e.clientY;
    return cursor.matrixTransform(m.inverse());
  }
  function bodyPoint(p){
    const a=pose[channel.torsoRoll]*rad,c=Math.cos(a),s=Math.sin(a);
    const x=p.x-hipX,y=p.y-hipY-pose[channel.torsoRise];
    return {x:hipX+c*x+s*y,y:hipY-s*x+c*y};
  }
  function relativeToPin(p){
    const q=bodyPoint(p);
    return [q.x-pinX-.30*pose[channel.breath]-1.65*pose[channel.sway],
            q.y-pinY+3.15*pose[channel.breath]];
  }
  function earPoint(binding,withDrag=true) {
    let x=binding.x,y=binding.y;
    for(let j=0;j<binding.k.length;j++){
      const k=binding.k[j];
      if(!withDrag&&k>=channel.earLDragCos)break;
      x+=binding.a[j]*pose[k];y+=binding.b[j]*pose[k];
    }
    return {x,y};
  }
  function beginEar(ear,p,e) {
    const contact=bodyPoint(p);
    // Locate the material point on the already posed cloth, including a previous rebound.
    let x=contact.x,y=contact.y;
    const sample=(x,y)=>earPoint(bind(x,y,ear.side));
    for(let i=0;i<6;i++){
      const q=sample(x,y),dx=contact.x-q.x,dy=contact.y-q.y;
      if(Math.hypot(dx,dy)<.015)break;
      const h=sample(x+1,y),v=sample(x,y+1);
      const a=h.x-q.x,b=h.y-q.y,c=v.x-q.x,d=v.y-q.y,det=a*d-b*c;
      if(Math.abs(det)<.1){x+=dx;y+=dy;}
      else{x+=(d*dx-c*dy)/det;y+=(a*dy-b*dx)/det;}
    }
    // Near the seam, transmit the tug into the free flap while leaving the stitching in place.
    const extension=Math.max(0,.40*ear.length-earDistance(ear,x,y));
    x+=extension*ear.nx;y+=extension*ear.ny;
    const binding=bind(x,y,ear.side),posed=earPoint(binding);
    const along=earDistance(ear,x,y),cross=ear.nx*(y-ear.root[1])-ear.ny*(x-ear.root[0]);
    earGrip={ear,id:e.pointerId,p,binding,along,cross,weight:earWeight(ear,along),
      offsetX:posed.x-contact.x,offsetY:posed.y-contact.y,captured:false};
    squeezeEyes(true);
    e.preventDefault?.();
    try{
      svg.setPointerCapture(e.pointerId);
      earGrip.captured=svg.hasPointerCapture?.(e.pointerId)??true;
    }catch(_){}
  }
  function updateEar(ear,dt){
    const grip=earGrip?.ear===ear?earGrip:null;
    let angle=0,slide=0;
    if(grip){
      const hand=bodyPoint(grip.p),base=earPoint(grip.binding,false);
      const dx=(hand.x+grip.offsetX-base.x)/grip.weight,dy=(hand.y+grip.offsetY-base.y)/grip.weight;
      const u=Math.max(.24*grip.along,grip.along+dx*ear.nx+dy*ear.ny);
      const v=grip.cross+ear.nx*dy-ear.ny*dx;
      // Resolve the grip into a bend and a limited displacement along the cloth.
      slide=clip(Math.sqrt(Math.max(0,u*u+v*v-grip.cross*grip.cross))-grip.along,-32,27);
      angle=clip(Math.atan2(v,u)-Math.atan2(grip.cross,grip.along+slide),-.27,.27);
    }
    const a=advance(ear.angle,angle,dt,grip ? 51 : ear.angle.w,grip ? .92 : ear.angle.z);
    const d=advance(ear.slide,slide,dt,grip ? 48 : ear.slide.w,grip ? .94 : ear.slide.z);
    const c=Math.cos(a),s=Math.sin(a);
    const [cos,sin,shiftX,shiftY]=ear.channels;
    pose[cos]=c-1;pose[sin]=s;
    pose[shiftX]=d*(c*ear.nx-s*ear.ny);pose[shiftY]=d*(s*ear.nx+c*ear.ny);
  }
  function letGoEar(){
    if(!earGrip)return;
    const id=earGrip.id;
    earGrip=null;
    try{if(svg.hasPointerCapture?.(id))svg.releasePointerCapture?.(id);}catch(_){}
    blinkStart=t-.128;nextBlink=Math.max(nextBlink,t+.55);doublePending=false;
    for(const eye of eyes)eye(1,irisX.x,irisY.x);
    squeezeEyes(false);
  }
  function hitPull(x,y){
    const c=Math.cos(pull.angle),s=Math.sin(pull.angle);
    const localX=c*x+s*y,localY=-s*x+c*y;
    return localY>=5&&localY<=98&&Math.abs(localX-.065*localY)<19;
  }
  function aim(p) {
    targetX=clip((p.x-986)/(p.x<986?550:460),-1,1);
    targetY=clip((p.y-392)/(p.y<392?350:430),-1,1);
  }
  function home() { targetX=0;targetY=0; }
  svg.addEventListener('pointermove',e=>{
    const p=pointInArt(e);if(!p)return;
    if(earGrip){
      if(e.pointerId===earGrip.id)earGrip.p=p;
      return;
    }
    if(pull.grip===null){aim(p);return;}
    if(e.pointerId!==pull.grip)return;
    const [x,y]=relativeToPin(p);
    pull.target=clip(Math.atan2(-x,Math.max(y,3))+pull.bias,-.72,.72);
  });
  svg.addEventListener('pointerdown',e=>{
    const p=pointInArt(e);if(!p||earGrip||pull.grip!==null||(e.button!=null&&e.button!==0))return;
    const ear=ears[e.target?.closest?.('[data-ear]')?.getAttribute('data-ear')];
    if(ear){beginEar(ear,p,e);return;}
    const [x,y]=relativeToPin(p);
    if(hitPull(x,y)){
      pull.grip=e.pointerId;pull.target=pull.angle;
      pull.bias=pull.angle-Math.atan2(-x,y);
      try{svg.setPointerCapture(e.pointerId);}catch(_){}
      return;
    }
    aim(p);
    if(e.pointerType!=='mouse'&&e.isPrimary!==false){
      touch=e.pointerId;
      try{svg.setPointerCapture(touch);}catch(_){}
    }
  });
  function release(e) {
    if(earGrip&&e.pointerId===earGrip.id){
      letGoEar();
      const p=e.type==='pointerup'&&e.pointerType==='mouse'?pointInArt(e):null;
      if(p&&p.x>=0&&p.x<=1536&&p.y>=0&&p.y<=1024)aim(p);else home();
    }
    if(e.pointerId===pull.grip)pull.grip=null;
    if(e.pointerId===touch){touch=null;home();}
  }
  svg.addEventListener('pointerup',release);
  svg.addEventListener('pointercancel',e=>{
    release(e);
    if(!earGrip&&touch===null&&pull.grip===null)home();
  });
  svg.addEventListener('lostpointercapture',release);
  win.addEventListener('pointerup',release);
  svg.addEventListener('pointerleave',()=>{
    if(earGrip&&!earGrip.captured)letGoEar();
    if(!earGrip&&touch===null&&pull.grip===null)home();
  });
  function clearInteraction(){letGoEar();touch=null;pull.grip=null;home();}
  win.addEventListener('blur',clearInteraction);

  const motion=win.matchMedia('(prefers-reduced-motion: reduce)');
  let t=0, nextBlink=1.85, blinkStart=-10, doublePending=false;
  let nextGlance=2.65, glanceX=0, glanceY=0;
  function blinking(age) {
    if(age<0||age>=.265)return 0;
    if(age<.098)return smooth(0,.098,age);
    if(age<.129)return 1;
    return 1-smooth(.129,.265,age);
  }
  function physics(dt,quiet,loopDuration=0) {
    t+=dt;
    // A periodic forcing option lets an SVG image embed bake the very same spring chains.
    function rateForCycle(rate){
      if(loopDuration)rate=Math.max(1,Math.round(rate*loopDuration/(2*Math.PI)))*2*Math.PI/loopDuration;
      return rate;
    }
    function wave(rate,phase=0) {
      return Math.sin(rateForCycle(rate)*t+phase);
    }
    const idle=quiet ? .14 : 1;
    const sway=wave(.77),breath=wave(1.42)*.85+wave(2.84,-.9)*.15;
    const x=advance(headX,clip(targetX+gravityX,-1,1)+idle*(.050*wave(.73)+.018*wave(1.61)),dt);
    const y=advance(headY,clip(targetY+gravityY,-1,1)+idle*(.044*wave(.89)+.016*wave(1.42)),dt);
    const lastRollSpeed=torsoRoll.v;
    // The chest follows the head on a slower spring. The pelvis is the rotation pivot.
    pose[channel.torsoRoll]=advance(torsoRoll,.98*x+idle*(.22*wave(.77,-.30)+.075*wave(1.37,.60)),dt);
    pose[channel.torsoRise]=advance(torsoRise,1.65*y+idle*.24*wave(.93,-.62),dt);
    advance(irisX,clip(targetX+gravityX,-1,1)+.085*glanceX*idle,dt);advance(irisY,clip(targetY+gravityY,-1,1)+.095*glanceY*idle,dt);
    const lean=advance(roll,.37*x+.08*y+idle*(.28*sway+.12*wave(1.38)),dt);
    const impulse=clip(headX.v,-2.7,2.7),nod=clip(headY.v,-2.45,2.45);
    pose[channel.breath]=breath*idle;pose[channel.sway]=sway*idle;
    projectHead(.128*x,.074*y,rad*lean);
    for(const c of chains){
      const breeze=c.wind*idle*(.78*wave(c.period,c.phase)+.32*wave(c.period*1.78,c.phase-.69));
      const drive=c.impulse*impulse+c.nod*nod+.23*roll.v+.14*x+.12*torsoRoll.v;
      const bend=advance(c.root,clip(drive+breeze,-4.5,4.5),dt);
      const tipWind=idle*c.wind*.35*wave(c.period*1.37,c.phase-.92);
      const tail=advance(c.tip,clip(.66*bend-.12*c.root.v+.15*c.impulse*impulse+tipWind,-3.7,3.7),dt);
      pose[c.joint[3]]=bend;pose[c.joint[4]]=tail;
    }
    updateEar(ears.earL,dt);updateEar(ears.earR,dt);
    const lastArmV=arm.v,lastSleeveV=sleeve.v;
    const sh=advance(arm,-.30*y+.16*x+idle*(.72*wave(1.12)+.25*wave(.54)),dt);
    const el=advance(elbow,-.27*sh-.21*arm.v+idle*.40*wave(1.43,.28),dt);
    pose[channel.shoulder]=sh;pose[channel.elbow]=el;
    pose[channel.wrist]=advance(wrist,-.38*el-.42*elbow.v-.26*arm.v+idle*.47*wave(1.87),dt);
    pose[channel.cuff]=advance(cuff,-.91*arm.v-.68*elbow.v+idle*.64*wave(1.66),dt);
    pose[channel.sleeve]=advance(sleeve,-.23*x+idle*(.60*wave(1.34,-.72)+.25*breath),dt);
    const bodyAx=-idle*(1.65*rateForCycle(.77)**2*sway+.30*(.85*rateForCycle(1.42)**2*wave(1.42)+.15*rateForCycle(2.84)**2*wave(2.84,-.9)));
    const hingeAx=(hipY-pinY)*rad*(torsoRoll.v-lastRollSpeed)/dt;
    swingPull(dt,bodyAx+hingeAx,(arm.v-lastArmV)/dt,(sleeve.v-lastSleeveV)/dt,pose[channel.torsoRoll]*rad);
  }

  // Keep a declarative breathing/blinking version alive in script-free SVG image contexts.
  // Only switch it off after all interactive bindings have initialized successfully.
  svg.querySelectorAll('.passive').forEach(n=>n.remove());
  let last=0, raf=0, welcomeActive=false, welcomeReduced=false;
  win.setWelcomeTilt=(x,y)=>{
    gravityX=welcomeReduced?0:clip(-x,-1,1)*.42;
    gravityY=welcomeReduced?0:clip(y,-1,1)*.28;
  };
  function syncWelcomeMotion(){
    win.cancelAnimationFrame(raf);last=0;
    if(welcomeActive&&!svg.ownerDocument.hidden)raf=win.requestAnimationFrame(frame);
    else clearInteraction();
  }
  win.setWelcomeMotion=(active,reduced)=>{
    welcomeActive=active;
    welcomeReduced=reduced;
    if(reduced||!active)gravityX=gravityY=0;
    syncWelcomeMotion();
  };
  function frame(now) {
    raf=win.requestAnimationFrame(frame);
    if(last&&now-last<14.5)return;
    const delta=last?Math.min((now-last)/1000,.050):1/60;
    last=now;
    const n=Math.ceil(delta/.0083),step=delta/n;
    for(let j=0;j<n;j++)physics(step,welcomeReduced||motion.matches);
    if(t>=nextGlance){glanceX=Math.random()*2-1;glanceY=Math.random()*2-1;nextGlance=t+1.8+Math.random()*3;}
    if(t>=nextBlink){
      blinkStart=t;
      if(!doublePending&&Math.random()<.13){nextBlink=t+.40+Math.random()*.07;doublePending=true;}
      else{nextBlink=t+2.9+Math.random()*2.7;doublePending=false;}
    }
    const bl=blinking(t-blinkStart),br=blinking(t-blinkStart-.008);
    pose[channel.lid]=(bl+br)*.5;
    paintSkin();
    eyes[0](bl,irisX.x,irisY.x);eyes[1](br,irisX.x,irisY.x);
  }
  svg.ownerDocument.addEventListener('visibilitychange',syncWelcomeMotion);
})();
